#include "module/i2c_register_device.hpp"
namespace fw::module{fw::Result<void>I2cRegisterDevice::read(std::uint8_t r,std::uint8_t*d,std::size_t n,fw::bsp::TransferMode m,std::uint32_t t){if(!d||!n)return fw::Result<void>::failure(fw::Error::InvalidArgument);auto x=bus_.write(address_,&r,1,fw::bsp::TransferMode::Blocking,t);if(!x)return x;return bus_.read(address_,d,n,m,t);}fw::Result<void>I2cRegisterDevice::write(std::uint8_t r,const std::uint8_t*d,std::size_t n,std::uint32_t t){if(!d||!n||n>=32)return fw::Result<void>::failure(fw::Error::InvalidArgument);std::uint8_t b[32];b[0]=r;for(std::size_t i=0;i<n;i++)b[i+1]=d[i];return bus_.write(address_,b,n+1,fw::bsp::TransferMode::Blocking,t);}}
